__global__ void fused_add_scale_kernel(
    float* C,
    const float* A,
    const float* B,
    int width,
    float scale
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < width && col < width) {
        int idx = row * width + col;
        C[idx] = (A[idx] + B[idx]) * scale;
    }
}

void fused_add_scale(
    float* C,
    const float* A,
    const float* B,
    int width,
    float scale
) {
    const int BLOCK_SIZE = 16;

    dim3 blockDim(BLOCK_SIZE, BLOCK_SIZE);
    int grid_dim_x = (width + BLOCK_SIZE - 1) / BLOCK_SIZE;
    int grid_dim_y = (width + BLOCK_SIZE - 1) / BLOCK_SIZE;
    dim3 gridDim(grid_dim_x, grid_dim_y);

    fused_add_scale_kernel<<<gridDim, blockDim>>>(C, A, B, width, scale);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
}
