void cpu_reference(float* C, const float* A, const float* B, int width, float scale) {
    for (int i = 0; i < width * width; i++) {
        C[i] = (A[i] + B[i]) * scale;
    }
}

bool compare_matrices(const float* C1, const float* C2, int size, float tol = 1e-5) {
    float max_diff = 0.0f;
    for (int i = 0; i < size; i++) {
        float diff = std::abs(C1[i] - C2[i]);
        max_diff = std::max(max_diff, diff);
        if (diff > tol) {
            std::cout << "Mismatch at index " << i << ": " << C1[i] << " vs " << C2[i] << std::endl;
            return false;
        }
    }
    std::cout << "Max difference: " << max_diff << std::endl;
    return true;
}

int main() {
    // Test with small matrix
    {
        int width = 4;
        float scale = 2.0f;
        int size = width * width;

        DeviceBuffer<float> d_A(size, true);
        DeviceBuffer<float> d_B(size, true);
        DeviceBuffer<float> d_C(size, false);

        fused_add_scale(d_C.devPtr, d_A.devPtr, d_B.devPtr, width, scale);

        float* cpu_C = new float[size];
        cpu_reference(cpu_C, d_A.hostPtr, d_B.hostPtr, width, scale);

        CUDA_CHECK(cudaMemcpy(d_C.hostPtr, d_C.devPtr, size * sizeof(float), cudaMemcpyDeviceToHost));

        std::cout << "Test 4x4 matrix: ";
        if (compare_matrices(d_C.hostPtr, cpu_C, size)) {
            std::cout << "PASSED" << std::endl;
        } else {
            std::cout << "FAILED" << std::endl;
            delete[] cpu_C;
            return 1;
        }
        delete[] cpu_C;
    }

    // Test with larger matrix
    {
        int width = 64;
        float scale = 0.5f;
        int size = width * width;

        DeviceBuffer<float> d_A(size, true);
        DeviceBuffer<float> d_B(size, true);
        DeviceBuffer<float> d_C(size, false);

        fused_add_scale(d_C.devPtr, d_A.devPtr, d_B.devPtr, width, scale);

        float* cpu_C = new float[size];
        cpu_reference(cpu_C, d_A.hostPtr, d_B.hostPtr, width, scale);

        CUDA_CHECK(cudaMemcpy(d_C.hostPtr, d_C.devPtr, size * sizeof(float), cudaMemcpyDeviceToHost));

        std::cout << "Test 64x64 matrix: ";
        if (compare_matrices(d_C.hostPtr, cpu_C, size)) {
            std::cout << "PASSED" << std::endl;
        } else {
            std::cout << "FAILED" << std::endl;
            delete[] cpu_C;
            return 1;
        }
        delete[] cpu_C;
    }

    // Test with odd dimension
    {
        int width = 17;
        float scale = -1.0f;
        int size = width * width;

        DeviceBuffer<float> d_A(size, true);
        DeviceBuffer<float> d_B(size, true);
        DeviceBuffer<float> d_C(size, false);

        fused_add_scale(d_C.devPtr, d_A.devPtr, d_B.devPtr, width, scale);

        float* cpu_C = new float[size];
        cpu_reference(cpu_C, d_A.hostPtr, d_B.hostPtr, width, scale);

        CUDA_CHECK(cudaMemcpy(d_C.hostPtr, d_C.devPtr, size * sizeof(float), cudaMemcpyDeviceToHost));

        std::cout << "Test 17x17 matrix: ";
        if (compare_matrices(d_C.hostPtr, cpu_C, size)) {
            std::cout << "PASSED" << std::endl;
        } else {
            std::cout << "FAILED" << std::endl;
            delete[] cpu_C;
            return 1;
        }
        delete[] cpu_C;
    }

    std::cout << "All tests passed!" << std::endl;
    return 0;
}
