#include "helpers.h"

__global__ void set_union_with_scale_kernel(
    const int* __restrict__ d_a,
    const int* __restrict__ d_b,
    int* __restrict__ d_result,
    int size_a,
    int size_b,
    int scale_factor
) {
    int idx = threadIdx.x;
    int start_a, start_b;

    int elements_per_thread_a = (size_a + blockDim.x - 1) / blockDim.x;
    int elements_per_thread_b = (size_b + blockDim.x - 1) / blockDim.x;

    start_a = idx * elements_per_thread_a;
    start_b = idx * elements_per_thread_b;

    int end_a = min(start_a + elements_per_thread_a, size_a);
    int end_b = min(start_b + elements_per_thread_b, size_b);

    int local_a_size = end_a - start_a;
    int local_b_size = end_b - start_b;

    extern __shared__ int shared_mem[];

    int* a_chunk = shared_mem;
    int* b_chunk = a_chunk + elements_per_thread_a;
    int* result_chunk = b_chunk + elements_per_thread_b;

    for (int i = 0; i < local_a_size; ++i) {
        a_chunk[i] = d_a[start_a + i];
    }
    for (int i = 0; i < local_b_size; ++i) {
        b_chunk[i] = d_b[start_b + i];
    }

    __syncthreads();

    int a_ptr = 0, b_ptr = 0, res_ptr = 0;

    while (a_ptr < local_a_size && b_ptr < local_b_size) {
        int a_val = a_chunk[a_ptr];
        int b_val = b_chunk[b_ptr];

        if (a_val < b_val) {
            result_chunk[res_ptr++] = a_val * scale_factor;
            a_ptr++;
        } else if (b_val < a_val) {
            result_chunk[res_ptr++] = b_val * scale_factor;
            b_ptr++;
        } else {
            result_chunk[res_ptr++] = a_val * scale_factor;
            result_chunk[res_ptr++] = b_val * scale_factor;
            a_ptr++;
            b_ptr++;
        }
    }

    while (a_ptr < local_a_size) {
        result_chunk[res_ptr++] = a_chunk[a_ptr++] * scale_factor;
    }

    while (b_ptr < local_b_size) {
        result_chunk[res_ptr++] = b_chunk[b_ptr++] * scale_factor;
    }

    int global_offset = (elements_per_thread_a + elements_per_thread_b) * idx;

    for (int i = 0; i < res_ptr; ++i) {
        d_result[global_offset + i] = result_chunk[i];
    }
}

void set_union_with_scale(
    const int* d_a,
    const int* d_b,
    int* d_result,
    int size_a,
    int size_b,
    int scale_factor
) {
    int block_size = 256;
    int grid_size = 1;

    int elements_per_thread_a = (size_a + block_size - 1) / block_size;
    int elements_per_thread_b = (size_b + block_size - 1) / block_size;
    size_t shared_mem_size = (elements_per_thread_a + elements_per_thread_b * 2) * sizeof(int);

    set_union_with_scale_kernel<<<grid_size, block_size, shared_mem_size>>>(
        d_a, d_b, d_result, size_a, size_b, scale_factor
    );

    CUDA_CHECK(cudaGetLastError());
}
