int main() {
    // Test case 1: Simple case
    std::vector<int> a = {1, 3, 5};
    std::vector<int> b = {2, 4, 6};
    int scale = 2;

    int *d_a, *d_b, *d_result;
    size_t size_a = a.size() * sizeof(int);
    size_t size_b = b.size() * sizeof(int);
    size_t size_result = (a.size() + b.size()) * sizeof(int);

    CUDA_CHECK(cudaMalloc(&d_a, size_a));
    CUDA_CHECK(cudaMalloc(&d_b, size_b));
    CUDA_CHECK(cudaMalloc(&d_result, size_result));

    CUDA_CHECK(cudaMemcpy(d_a, a.data(), size_a, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(d_b, b.data(), size_b, cudaMemcpyHostToDevice));

    set_union_with_scale(d_a, d_b, d_result, a.size(), b.size(), scale);

    std::vector<int> result(a.size() + b.size());
    CUDA_CHECK(cudaMemcpy(result.data(), d_result, size_result, cudaMemcpyDeviceToHost));

    std::cout << "Test 1 - Sorted arrays with no overlap:" << std::endl;
    std::cout << "A: [1, 3, 5], B: [2, 4, 6], scale: 2" << std::endl;
    std::cout << "Result: [";
    for (size_t i = 0; i < result.size(); ++i) {
        std::cout << result[i];
        if (i < result.size() - 1) std::cout << ", ";
    }
    std::cout << "]" << std::endl;
    std::cout << "Expected: [2, 4, 6, 8, 10, 12]" << std::endl << std::endl;

    cudaFree(d_a);
    cudaFree(d_b);
    cudaFree(d_result);

    return 0;
}
