{"content":"#include "solution_header.h"

__global__ void apply_growth_clamp_kernel(const float* source, const float* input,
                                          float* output, int n, float mu, float sigma, float weight) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= n) return;

    float x = input[idx];
    float diff = x - mu;
    float sigma_sq = sigma * sigma;
    float exp_val = expf(-(diff * diff) / sigma_sq);
    float growth = weight * (2.0f * exp_val - 1.0f);
    float y = growth + source[idx];

    if (y < 0.0f) {
        output[idx] = 0.0f;
    } else if (y > 1.0f) {
        output[idx] = 1.0f;
    } else {
        output[idx] = y;
    }
}

void apply_growth_clamp(const float* source, const float* input,
                        float* output, int n, float mu, float sigma, float weight) {
    int threads_per_block = 256;
    int blocks = (n + threads_per_block - 1) / threads_per_block;

    apply_growth_clamp_kernel<<<blocks, threads_per_block>>>(source, input, output, n, mu, sigma, weight);
    CUDA_CHECK(cudaGetLastError());
}
