void verify_result(const float* h_output, const float* h_source, const float* h_input,
                   int n, float mu, float sigma, float weight) {
    float max_error = 0.0f;
    int error_count = 0;

    for (int i = 0; i < n; i++) {
        float x = h_input[i];
        float diff = x - mu;
        float sigma_sq = sigma * sigma;
        float exp_val = expf(-(diff * diff) / sigma_sq);
        float growth = weight * (2.0f * exp_val - 1.0f);
        float y = growth + h_source[i];
        float expected = fmaxf(0.0f, fminf(1.0f, y));

        float error = fabsf(h_output[i] - expected);
        if (error > 1e-6f) {
            if (error_count < 10) {
                printf("Mismatch at index %d: got %.6f, expected %.6f\n", i, h_output[i], expected);
            }
            error_count++;
            max_error = fmaxf(max_error, error);
        }
    }

    if (error_count == 0) {
        printf("All tests passed!\n");
    } else {
        printf("Found %d mismatches, max error: %.6f\n", error_count, max_error);
    }
}

int main() {
