void test_growth_calculation() {
    printf("\n=== Testing Growth Calculation ===\n");

    const int n = 1;
    float h_source[] = {0.3f};
    float h_input[] = {0.5f};
    float h_output[n];

    float mu = 0.5f;
    float sigma = 1.0f;
    float weight = 1.0f;

    CudaDevicePtr<float> d_source(n);
    CudaDevicePtr<float> d_input(n);
    CudaDevicePtr<float> d_output(n);

    CUDA_CHECK(cudaMemcpy(d_source.get(), h_source, n * sizeof(float), cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(d_input.get(), h_input, n * sizeof(float), cudaMemcpyHostToDevice));

    apply_growth_clamp(d_source.get(), d_input.get(), d_output.get(), n, mu, sigma, weight);

    CUDA_CHECK(cudaMemcpy(h_output, d_output.get(), n * sizeof(float), cudaMemcpyDeviceToHost));

    float x = h_input[0];
    float diff = x - mu;
    float sigma_sq = sigma * sigma;
    float exp_val = expf(-(diff * diff) / sigma_sq);
    float growth = weight * (2.0f * exp_val - 1.0f);
    float y = growth + h_source[0];
    float expected = fmaxf(0.0f, fminf(1.0f, y));

    printf("Input: input=%.3f, source=%.3f\n", h_input[0], h_source[0]);
    printf("Parameters: mu=%.3f, sigma=%.3f, weight=%.3f\n", mu, sigma, weight);
    printf("Computed: growth=%.6f, y=%.6f, clamped=%.6f\n", growth, y, expected);
    printf("GPU output: %.6f\n", h_output[0]);

    if (fabsf(h_output[0] - expected) < 1e-6f) {
        printf("Growth calculation correct!\n");
    } else {
        printf("ERROR: Mismatch in growth calculation!\n");
    }
}

