#include <cub/cub.cuh>

template <int BLOCK_THREADS>
__global__ void find_minimum_kernel(
    const float* input,
    float* min_values,
    int* min_indices,
    int width
) {
    int row = blockIdx.y;
    int col = threadIdx.x;

    typedef cub::BlockReduce<cub::KeyValuePair<int, float>, BLOCK_THREADS> BlockReduce;
    __shared__ typename BlockReduce::TempStorage temp_storage;

    cub::KeyValuePair<int, float> thread_data;

    if (col < width) {
        thread_data.key = col;
        thread_data.value = input[row * width + col];
    } else {
        thread_data.key = 0;
        thread_data.value = CUB_INFINITY;
    }

    cub::ArgMin arg_min;
    cub::KeyValuePair<int, float> block_result = BlockReduce(temp_storage).Reduce(thread_data, arg_min);

    if (threadIdx.x == 0) {
        min_values[row] = block_result.value;
        min_indices[row] = block_result.key;
    }
}

void find_minimum(
    const float* input,
    float* min_values,
    int* min_indices,
    int height,
    int width
) {
    const int BLOCK_THREADS = 256;
    dim3 grid(1, height);
    dim3 block(BLOCK_THREADS);

    find_minimum_kernel<BLOCK_THREADS><<<grid, block>>>(input, min_values, min_indices, width);
    cudaDeviceSynchronize();
}
