void cpu_reference(const float* input, float* min_values, int* min_indices, int height, int width) {
    for (int row = 0; row < height; row++) {
        float min_val = input[row * width];
        int min_idx = 0;
        for (int col = 1; col < width; col++) {
            float val = input[row * width + col];
            if (val < min_val) {
                min_val = val;
                min_idx = col;
            }
        }
        min_values[row] = min_val;
        min_indices[row] = min_idx;
    }
}

int main() {
    std::cout << "Testing row-wise minimum finder...\n";

    const int height = 8;
    const int width = 16;
    const int total = height * width;

    std::vector<float> h_input(total);
    std::vector<float> h_min_values_gpu(height);
    std::vector<float> h_min_values_cpu(height);
    std::vector<int> h_min_indices_gpu(height);
    std::vector<int> h_min_indices_cpu(height);

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<float> dist(-100.0f, 100.0f);

    for (int i = 0; i < total; i++) {
        h_input[i] = dist(gen);
    }

    float *d_input, *d_min_values;
    int *d_min_indices;

    cudaMalloc(&d_input, total * sizeof(float));
    cudaMalloc(&d_min_values, height * sizeof(float));
    cudaMalloc(&d_min_indices, height * sizeof(int));

    cudaMemcpy(d_input, h_input.data(), total * sizeof(float), cudaMemcpyHostToDevice);

    find_minimum(d_input, d_min_values, d_min_indices, height, width);

    cudaMemcpy(h_min_values_gpu.data(), d_min_values, height * sizeof(float), cudaMemcpyDeviceToHost);
    cudaMemcpy(h_min_indices_gpu.data(), d_min_indices, height * sizeof(int), cudaMemcpyDeviceToHost);

    cpu_reference(h_input.data(), h_min_values_cpu.data(), h_min_indices_cpu.data(), height, width);

    bool passed = true;
    for (int i = 0; i < height; i++) {
        if (std::abs(h_min_values_gpu[i] - h_min_values_cpu[i]) > 1e-5f ||
            h_min_indices_gpu[i] != h_min_indices_cpu[i]) {
            std::cout << "Row " << i << " FAILED:\n";
            std::cout << "  GPU: min=" << h_min_values_gpu[i] << " idx=" << h_min_indices_gpu[i] << "\n";
            std::cout << "  CPU: min=" << h_min_values_cpu[i] << " idx=" << h_min_indices_cpu[i] << "\n";
            passed = false;
        }
    }

    if (passed) {
        std::cout << "ALL TESTS PASSED!\n";
    } else {
        std::cout << "SOME TESTS FAILED!\n";
    }

    cudaFree(d_input);
    cudaFree(d_min_values);
    cudaFree(d_min_indices);

    return passed ? 0 : 1;
}
