__global__ void broadcast_add_kernel(
    const float* x,
    const float* y,
    float* output,
    int x_dim0,
    int y_dim0,
    int dim1
) {
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < x_dim0 && j < dim1) {
        float x_val = x[i];
        int y_i = i % y_dim0;
        float y_val = y[y_i * dim1 + j];
        output[i * dim1 + j] = x_val + y_val;
    }
}

void broadcast_add(
    const float* x,
    const float* y,
    float* output,
    int x_dim0,
    int y_dim0,
    int dim1
) {
    dim3 blockDim(16, 16);
    dim3 gridDim((dim1 + blockDim.x - 1) / blockDim.x, (x_dim0 + blockDim.y - 1) / blockDim.y);

    broadcast_add_kernel<<<gridDim, blockDim>>>(x, y, output, x_dim0, y_dim0, dim1);
    cudaDeviceSynchronize();
}
