__global__ void distanceMatrixKernel(
    const float2* __restrict__ points_A,
    const float2* __restrict__ points_B,
    float* __restrict__ distances,
    int M,
    int N
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float2 a = points_A[row];
        float2 b = points_B[col];
        float dx = a.x - b.x;
        float dy = a.y - b.y;
        distances[row * N + col] = dx * dx + dy * dy;
    }
}

void computeDistanceMatrix(
    const float2* __restrict__ points_A,
    const float2* __restrict__ points_B,
    float* __restrict__ distances,
    int M,
    int N
) {
    dim3 blockDim(16, 16);
    dim3 gridDim((N + blockDim.x - 1) / blockDim.x, (M + blockDim.y - 1) / blockDim.y);

    distanceMatrixKernel<<<gridDim, blockDim>>>(points_A, points_B, distances, M, N);
}
