__global__ void partitioned_prefix_sum_kernel(
    const float* input,
    float* prefix_sum,
    int* chunk_ids,
    int n,
    int chunk_size
) {
    extern __shared__ float shared_data[];

    int global_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int chunk_id = global_idx / chunk_size;

    if (global_idx < n) {
        shared_data[threadIdx.x] = input[global_idx];
        chunk_ids[global_idx] = chunk_id;
    } else {
        shared_data[threadIdx.x] = 0.0f;
    }
    __syncthreads();

    if (global_idx < n) {
        float sum = 0.0f;
        int start_idx = max(0, (blockIdx.x * blockDim.x + threadIdx.x) / chunk_size * chunk_size);
        int end_idx = min(start_idx + chunk_size, n);

        int local_pos = global_idx - start_idx;

        for (int i = start_idx; i <= global_idx && i < end_idx; i++) {
            sum += input[i];
        }

        prefix_sum[global_idx] = sum;
    }

    if (global_idx < n) {
        int start_idx = (chunk_id * chunk_size);
        int num_elements = min(chunk_size, n - start_idx);

        float chunk_sum = 0.0f;
        for (int i = blockIdx.x * blockDim.x; i < (blockIdx.x + 1) * blockDim.x && i < n; i++) {
            int current_chunk = i / chunk_size;
            if (current_chunk < chunk_id) {
                chunk_sum += input[i];
            }
        }
        __syncthreads();

        if (blockIdx.x > 0) {
            float* prev_block_sum = (float*)shared_data;
            if (threadIdx.x == 0) {
                prev_block_sum[0] = 0.0f;
            }
            __syncthreads();

            int elements_per_thread = (blockDim.x + blockDim.x - 1) / blockDim.x;
            float local_sum = 0.0f;
            for (int i = threadIdx.x * elements_per_thread; 
                 i < min((threadIdx.x + 1) * elements_per_thread, blockDim.x) && 
                 (blockIdx.x * blockDim.x + i) < n; i++) {
                if ((blockIdx.x * blockDim.x + i) / chunk_size < chunk_id) {
                    local_sum += shared_data[i];
                }
            }

            __shared__ float block_sums[256];
            block_sums[threadIdx.x] = local_sum;
            __syncthreads();

            for (int s = blockDim.x / 2; s > 0; s >>= 1) {
                if (threadIdx.x < s) {
                    block_sums[threadIdx.x] += block_sums[threadIdx.x + s];
                }
                __syncthreads();
            }

            if (global_idx < n) {
                int prev_chunks_start = chunk_id * chunk_size;
                float prev_chunk_sum = 0.0f;
                for (int c = 0; c < chunk_id; c++) {
                    int c_start = c * chunk_size;
                    int c_end = min(c_start + chunk_size, n);
                    for (int j = c_start; j < c_end; j++) {
                        prev_chunk_sum += input[j];
                    }
                }
                prefix_sum[global_idx] += prev_chunk_sum;
            }
        }
    }
}

void partitioned_prefix_sum(
    const float* input,
    float* prefix_sum,
    int* chunk_ids,
    int n,
    int chunk_size
) {
    const int BLOCK_SIZE = 256;
    int grid_size = (n + BLOCK_SIZE - 1) / BLOCK_SIZE;

    size_t shared_mem_size = BLOCK_SIZE * sizeof(float);

    partitioned_prefix_sum_kernel<<<grid_size, BLOCK_SIZE, shared_mem_size>>>(
        input, prefix_sum, chunk_ids, n, chunk_size
    );

    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
}
