    int chunk_size
) {
    __shared__ float shared_input[256];

    int global_idx = blockIdx.x * blockDim.x + threadIdx.x;

    int chunk_id = global_idx / chunk_size;
    int chunk_start = chunk_id * chunk_size;
    int chunk_end = min(chunk_start + chunk_size, n);
    int pos_in_chunk = global_idx - chunk_start;

    if (global_idx < n) {
        chunk_ids[global_idx] = chunk_id;

        int local_block_idx = chunk_start - blockIdx.x * blockDim.x + threadIdx.x;
        if (local_block_idx >= 0 && local_block_idx < blockDim.x) {
            shared_input[local_block_idx] = input[chunk_start + threadIdx.x];
        }
    }
    __syncthreads();

    if (global_idx < n && pos_in_chunk >= 0 && pos_in_chunk < chunk_size) {
        float sum = 0.0f;
        for (int i = chunk_start; i <= global_idx && i < chunk_end; i++) {
            int local_idx = i - blockIdx.x * blockDim.x;
            if (local_idx >= 0 && local_idx < blockDim.x && i >= blockIdx.x * blockDim.x && i < (blockIdx.x + 1) * blockDim.x) {
                sum += shared_input[local_idx];
            } else {
                sum += input[i];
            }
        }
        prefix_sum[global_idx] = sum;
    }

    if (global_idx < n && chunk_id > 0) {
        float prev_chunks_sum = 0.0f;

        __shared__ float chunk_sum;
        if (threadIdx.x == 0) {
            chunk_sum = 0.0f;
        }
        __syncthreads();

        for (int c = 0; c < chunk_id; c++) {
            int c_start = c * chunk_size;
            int c_end = min(c_start + chunk_size, n);
            float this_chunk_sum = 0.0f;

            int c_block_id = c_start / blockDim.x;
            if (c_block_id == blockIdx.x) {
                int elements_in_this_block = c_end - c_start;
                int start_local = c_start - blockIdx.x * blockDim.x;
                for (int i = 0; i < elements_in_this_block; i++) {
                    this_chunk_sum += shared_input[start_local + i];
                }
            } else if (c_block_id < blockIdx.x) {
                for (int i = c_start; i < c_end; i++) {
                    this_chunk_sum += input[i];
                }
            }
            prev_chunks_sum += this_chunk_sum;
        }

        prefix_sum[global_idx] += prev_chunks_sum;
    }
}

void partitioned_prefix_sum(
    const float* input,
