        for (int i = threadIdx.x; i < blockDim.x && (block_start + i) < n; i += blockDim.x) {
            prefix_input[i] = input[block_start + i];
        }
        __syncthreads();

        float block_prefix = 0.0f;
        for (int i = 0; i < blockDim.x && (block_start + i) <= global_idx && (block_start + i) < n; i++) {
            block_prefix += prefix_input[i];
        }

        __shared__ float total_block_sum;
        if (threadIdx.x == 0) {
            total_block_sum = 0.0f;
            for (int i = 0; i < blockDim.x && (block_start + i) < n; i++) {
                total_block_sum += prefix_input[i];
            }
        }
        __syncthreads();

        for (int c = 0; c < chunk_id; c++) {
            int c_start = c * chunk_size;
            int c_end = min(c_start + chunk_size, n);
            int c_block_start = (c_start / blockDim.x) * blockDim.x;

            if (c_block_start < block_start) {
                for (int i = c_start; i < c_end; i++) {
                    prev_chunks_sum += input[i];
                }
            }
        }

        prefix_sum[global_idx] += prev_chunks_sum;
    }
}

void partitioned_prefix_sum(
    const float* input,
    float* prefix_sum,
    int* chunk_ids,
    int n,
    int chunk_size
) {
    const int BLOCK_SIZE = 256;
    int grid_size = (n + BLOCK_SIZE - 1) / BLOCK_SIZE;

    partitioned_prefix_sum_kernel<<<grid_size, BLOCK_SIZE>>>(
        input, prefix_sum, chunk_ids, n, chunk_size
    );

    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
}
