__inline__ __device__ float warp_reduce_max(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    }
    return val;
}

__inline__ __device__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

__global__ void scaled_dot_product_attention_kernel(
    const float* __restrict__ Q,
    const float* __restrict__ K,
    const float* __restrict__ V,
    float* __restrict__ output,
    int seq_len,
    int head_dim,
    float scale) {

    int query_idx = blockIdx.x;
    int key_idx = threadIdx.x;

    extern __shared__ float s_data[];
    float* s_scores = s_data;
    float* s_attn = s_data + seq_len;

    if (key_idx >= seq_len) return;

    float score = 0.0f;
    const float* q_row = Q + query_idx * head_dim;
    const float* k_row = K + key_idx * head_dim;

    for (int d = 0; d < head_dim; d++) {
        score += q_row[d] * k_row[d];
    }
    score *= scale;

    s_scores[key_idx] = score;

    __syncthreads();

    float max_score = s_scores[0];
    for (int i = 1; i < seq_len; i++) {
        max_score = fmaxf(max_score, s_scores[i]);
    }

    __syncthreads();

    float exp_score = __expf(s_scores[key_idx] - max_score);
    s_attn[key_idx] = exp_score;

    __syncthreads();

    float sum_exp = s_attn[0];
    for (int i = 1; i < seq_len; i++) {
        sum_exp += s_attn[i];
    }

    __syncthreads();

    float attn_weight = s_attn[key_idx] / sum_exp;

    float* out_row = output + query_idx * head_dim;

    for (int d = 0; d < head_dim; d++) {
        float v_val = V[key_idx * head_dim + d];
        atomicAdd(&out_row[d], attn_weight * v_val);
    }
}

int scaled_dot_product_attention(
    const float* Q,
    const float* K,
    const float* V,
    float* output,
    int seq_len,
    int head_dim,
    float scale) {

    cudaMemset(output, 0, seq_len * head_dim * sizeof(float));

    int shared_mem_size = 2 * seq_len * sizeof(float);

    dim3 block(seq_len);
    dim3 grid(seq_len);

    scaled_dot_product_attention_kernel<<<grid, block, shared_mem_size>>>(
        Q, K, V, output, seq_len, head_dim, scale);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        return -1;
    }

    err = cudaDeviceSynchronize();
    if (err != cudaSuccess) {
        return -1;
    }

    return 0;
}
