    for (int i = 0; i < seq_len; i++) {
        for (int j = 0; j < head_dim; j++) {
            output[i * head_dim + j] = 0.0f;
        }
    }

    for (int i = 0; i < seq_len; i++) {
        std::vector<float> scores(seq_len);
        for (int j = 0; j < seq_len; j++) {
            float sum = 0.0f;
            for (int k = 0; k < head_dim; k++) {
                sum += Q[i * head_dim + k] * K[j * head_dim + k];
            }
            scores[j] = scale * sum;
        }

        float max_score = scores[0];
        for (int j = 1; j < seq_len; j++) {
            max_score = fmaxf(max_score, scores[j]);
        }

        float sum_exp = 0.0f;
        std::vector<float> attn(seq_len);
        for (int j = 0; j < seq_len; j++) {
            attn[j] = expf(scores[j] - max_score);
            sum_exp += attn[j];
        }

        for (int j = 0; j < seq_len; j++) {
            attn[j] /= sum_exp;
            for (int k = 0; k < head_dim; k++) {
                output[i * head_dim + k] += attn[j] * V[j * head_dim + k];
            }
        }
    }
}

bool compare_outputs(const float* gpu_output, const float* cpu_output, int size, float tol) {
    float max_diff = 0.0f;
    for (int i = 0; i < size; i++) {
