__global__ void row_minima_kernel(const float* __restrict__ A, float* minima, int width) {
    extern __shared__ float sdata[];

    int row = blockIdx.x;
    int col = threadIdx.x;
    int tid = threadIdx.x;

    float min_val = (col < width) ? A[row * width + col] : __int_as_float(0x7fffffff);

    for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
        if (tid < stride) {
            float other = (tid + stride < width) ? __shfl_down_sync(0xFFFFFFFF, min_val, stride) : __int_as_float(0x7fffffff);
            min_val = fminf(min_val, other);
        }
    }

    if (tid == 0) {
        minima[row] = min_val;
    }
}

