    int M = A.height;
    int N = A.width;
    const float* A_data = A.element;

    dim3 blockDim(256);
    dim3 gridDim(M);

    row_minima_kernel<<<gridDim, blockDim>>>(A_data, minima, N);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
}
