            float other = (tid + stride < width) ? __shfl_down_sync(0xFFFFFFFF, min_val, stride) : __int_as_float(0x7fffffff);
            min_val = fminf(min_val, other);
        }
    }

    if (tid == 0) {
        minima[row] = min_val;
    }
}

void find_row_minima(const Matrix A, float* minima) {
    int M = A.height;
    int N = A.width;
    const float* A_data = A.element;

    dim3 blockDim(256);
    dim3 gridDim(M);

    row_minima_kernel<<<gridDim, blockDim>>>(A_data, minima, N);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
}"}

