__global__ void cumulative_max_kernel(const float* input, float* cumulative_max, int* max_positions, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < size) {
        float max_val = input[0];
        int max_pos = 0;

        for (int i = 1; i <= idx; i++) {
            if (input[i] > max_val) {
                max_val = input[i];
                max_pos = i;
            }
        }

        cumulative_max[idx] = max_val;
        max_positions[idx] = max_pos;
    }
}

void cumulative_max_with_positions(
    const float* input,
    float* cumulative_max,
    int* max_positions,
    int size
) {
    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;

    cumulative_max_kernel<<<grid_size, block_size>>>(input, cumulative_max, max_positions, size);
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        return;
    }
}
