__global__ void conditionalVecAddKernel(
    const double* A,
    const double* B,
    double* C,
    int numElements,
    double threshold,
    int* counter
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;

    if (tid < numElements) {
        C[tid] = A[tid] + B[tid];
        if (C[tid] > threshold) {
            atomicAdd(counter, 1);
        }
    }
}

void conditionalVecAdd(
    const double* A,
    const double* B,
    double* C,
    int numElements,
    double threshold,
    int* counter
) {
    CUDA_CHECK(cudaMemset(counter, 0, sizeof(int)));

    int threadsPerBlock = 256;
    int blocksPerGrid = (numElements + threadsPerBlock - 1) / threadsPerBlock;

    conditionalVecAddKernel<<<blocksPerGrid, threadsPerBlock>>>(
        A, B, C, numElements, threshold, counter
    );

    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
}
