int main() {
    int n = 1000;
    double threshold = 10.0;

    Surface<double> A(n);
    Surface<double> B(n);
    Surface<double> C(n);
    Surface<int> counter(1, false);

    std::mt19937 gen(42);
    std::uniform_real_distribution<double> dist(0.0, 20.0);

    int expected_count = 0;
    for (int i = 0; i < n; i++) {
        A.hostPtr[i] = dist(gen);
        B.hostPtr[i] = dist(gen);
        double sum = A.hostPtr[i] + B.hostPtr[i];
        if (sum > threshold) {
            expected_count++;
        }
    }

    CUDA_CHECK(cudaMemcpy(A.devPtr, A.hostPtr, n * sizeof(double), cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(B.devPtr, B.hostPtr, n * sizeof(double), cudaMemcpyHostToDevice));

    conditionalVecAdd(A.devPtr, B.devPtr, C.devPtr, n, threshold, counter.devPtr);

    CUDA_CHECK(cudaMemcpy(C.hostPtr, C.devPtr, n * sizeof(double), cudaMemcpyDeviceToHost));
    CUDA_CHECK(cudaMemcpy(counter.hostPtr, counter.devPtr, sizeof(int), cudaMemcpyDeviceToHost));

    bool correct = true;
    for (int i = 0; i < n; i++) {
        double expected = A.hostPtr[i] + B.hostPtr[i];
        if (fabs(C.hostPtr[i] - expected) > 1e-6) {
            printf("Error at index %d: expected %.6f, got %.6f\n", i, expected, C.hostPtr[i]);
            correct = false;
            break;
        }
    }

    if (counter.hostPtr[0] != expected_count) {
        printf("Counter error: expected %d, got %d\n", expected_count, counter.hostPtr[0]);
        correct = false;
    }

    if (correct) {
        printf("Test passed! Counter = %d\n", counter.hostPtr[0]);
    } else {
        printf("Test failed!\n");
    }

    return correct ? 0 : 1;
}
