__global__ void pow_matrix_rows_kernel(float* matrix, int num_rows, int num_cols) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= num_rows || col >= num_cols) {
        return;
    }

    if (row == 0) {
        return;
    }

    int power = row + 1;
    int idx = row * num_cols + col;
    matrix[idx] = powf(matrix[idx], power);
}

void pow_matrix_rows(float* d_matrix, int num_rows, int num_cols) {
    dim3 blockDim(16, 16);
    dim3 gridDim((num_cols + blockDim.x - 1) / blockDim.x, 
                 (num_rows + blockDim.y - 1) / blockDim.y);

    pow_matrix_rows_kernel<<<gridDim, blockDim>>>(d_matrix, num_rows, num_cols);
    cudaDeviceSynchronize();
}
