__global__ void spatialGaussianKernel(const float* d_input, float* d_output, int size, float center_x, float center_y, float sigma) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < size && col < size) {
        int idx = row * size + col;
        float dx = col - center_x;
        float dy = row - center_y;
        float weight = expf(-(dx * dx + dy * dy) / (sigma * sigma));
        d_output[idx] = d_input[idx] * weight;
    }
}

void applySpatialGaussianKernel(const float* d_input, float* d_output, int size, float center_x, float center_y, float sigma, dim3 blockDim, dim3 gridDim) {
    spatialGaussianKernel<<<gridDim, blockDim>>>(d_input, d_output, size, center_x, center_y, sigma);
}
