#include "../include/helpers.h"
#include <iostream>
#include <cmath>
#include <vector>

void cpuReference(const float* input, float* output, int size, float center_x, float center_y, float sigma) {
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            float dx = j - center_x;
            float dy = i - center_y;
            float weight = expf(-(dx * dx + dy * dy) / (sigma * sigma));
            output[i * size + j] = input[i * size + j] * weight;
        }
    }
}

bool compareArrays(const float* a, const float* b, int size, float eps = 1e-5) {
    for (int i = 0; i < size * size; i++) {
        if (fabsf(a[i] - b[i]) > eps) {
            std::cout << "Mismatch at index " << i << ": " << a[i] << " vs " << b[i] << std::endl;
            return false;
        }
    }
    return true;
}

int main() {
    int size = 8;
    float center_x = 3.5f;
    float center_y = 3.5f;
    float sigma = 2.0f;

    std::vector<float> h_input(size * size);
    std::vector<float> h_output(size * size);
    std::vector<float> h_reference(size * size);

    for (int i = 0; i < size * size; i++) {
        h_input[i] = i + 1.0f;
    }

    float *d_input, *d_output;
    CUDA_CHECK(cudaMalloc(&d_input, size * size * sizeof(float)));
    CUDA_CHECK(cudaMalloc(&d_output, size * size * sizeof(float)));

    CUDA_CHECK(cudaMemcpy(d_input, h_input.data(), size * size * sizeof(float), cudaMemcpyHostToDevice));

    dim3 blockDim(16, 16);
    dim3 gridDim((size + blockDim.x - 1) / blockDim.x, (size + blockDim.y - 1) / blockDim.y);

    applySpatialGaussianKernel(d_input, d_output, size, center_x, center_y, sigma, blockDim, gridDim);

    CUDA_CHECK(cudaMemcpy(h_output.data(), d_output, size * size * sizeof(float), cudaMemcpyDeviceToHost));

    cpuReference(h_input.data(), h_reference.data(), size, center_x, center_y, sigma);

    bool correct = compareArrays(h_output.data(), h_reference.data(), size);

    if (correct) {
        std::cout << "Test PASSED!" << std::endl;
    } else {
        std::cout << "Test FAILED!" << std::endl;
    }

    cudaFree(d_input);
    cudaFree(d_output);

    return correct ? 0 : 1;
}
